{"path": "tests/test_users.py", "file_text": "from app.api.handlers import handle_get_user, handle_create_user


def test_get_user_ok():
    assert handle_get_user({"id": "1"}) == (200, {"id": 1, "name": "Ada", "email": "ada@example.com"})


def test_get_user_invalid():
    assert handle_get_user({"id": "abc"})[0] == 400


def test_get_user_missing():
    assert handle_get_user({"id": "99"})[0] == 404

def test_create_user_ok():
    status, user = handle_create_user({"name": " Alice ", "email": "alice@example.com"})
    assert status == 201
    assert user["name"] == "Alice"
    assert user["email"] == "alice@example.com"
    assert "id" in user

    # Verify retrieval
    status, retrieved = handle_get_user({"id": str(user["id"])})
    assert status == 200
    assert retrieved == user

def test_create_user_invalid_name():
    assert handle_create_user({"name": "", "email": "a@b.com"})[0] == 400
    assert handle_create_user({"name": " " * 51, "email": "a@b.com"})[0] == 400

def test_create_user_invalid_email():
    assert handle_create_user({"name": "Bob", "email": "not-an-email"})[0] == 400

def test_create_user_duplicate_email():
    handle_create_user({"name": "Bob", "email": "bob@example.com"})
    assert handle_create_user({"name": "Bobby", "email": "BOB@example.com"}) == (409, {"error": "email already exists"})
"}

